:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #21262d;
  --text-primary: #ffffff;
  --text-secondary: #8b949e;
  --accent-blue: #475F91;
  --accent-cyan: #00f2fe;
  --accent-green: #4facfe;
  --border-color: rgba(255, 255, 255, 0.1);
  --border-hover: rgba(0, 242, 254, 0.5);
  --font-mono: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, Courier, monospace;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --sidebar-width: 260px;
  --header-height: 64px;
}

[data-theme="light"] {
  --bg-primary: #ffffff;
  --bg-secondary: #f6f8fa;
  --bg-tertiary: #e1e4e8;
  --text-primary: #24292e;
  --text-secondary: #586069;
  --border-color: rgba(0, 0, 0, 0.1);
  --border-hover: rgba(0, 112, 243, 0.5);
  --accent-cyan: #0070f3;
  --accent-green: #0051a8;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font-sans);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--accent-cyan);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--accent-green);
}

/* Typography */
h1, h2, h3, h4, h5 {
  color: var(--text-primary);
  font-weight: 600;
  margin-bottom: 1rem;
  line-height: 1.2;
}

h1 { font-size: 2.5rem; letter-spacing: -0.02em; margin-bottom: 1.5rem; }
h2 { font-size: 2rem; margin-top: 2rem; }
h3 { font-size: 1.5rem; }
p { color: var(--text-secondary); margin-bottom: 1.5rem; font-size: 1.1rem; }
ul, ol { margin-left: 1.5rem; margin-bottom: 1.5rem; color: var(--text-secondary); }

/* Layout & Navigation */
header.top-nav {
  position: fixed;
  top: 0; left: 0; right: 0;
  height: var(--header-height);
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 2rem;
  z-index: 100;
}

.nav-brand {
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--text-primary);
}

.nav-links {
  display: flex;
  gap: 1.5rem;
}

.nav-links a {
  color: var(--text-secondary);
  font-size: 0.95rem;
  font-weight: 500;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
}

.nav-utilities {
  display: flex;
  gap: 1rem;
  align-items: center;
}

.utility-btn {
  background: none;
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  padding: 0.4rem 0.8rem;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.9rem;
  transition: all 0.2s ease;
}

.utility-btn:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

/* Page Containers */
.page-container {
  padding-top: var(--header-height);
  display: flex;
  min-height: 100vh;
}

/* Sidebar Layout for Docs */
.sidebar {
  width: var(--sidebar-width);
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  height: calc(100vh - var(--header-height));
  position: fixed;
  top: var(--header-height);
  left: 0;
  overflow-y: auto;
  padding: 2rem 1rem;
  transition: transform 0.3s ease, width 0.3s ease;
}

.sidebar.collapsed {
  transform: translateX(-100%);
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.sidebar-nav a {
  color: var(--text-secondary);
  padding: 0.5rem 1rem;
  border-radius: 6px;
  display: block;
}

.sidebar-nav a:hover,
.sidebar-nav a.active {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.sidebar-nav-title {
  text-transform: uppercase;
  font-size: 0.75rem;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  margin-top: 1.5rem;
  margin-bottom: 0.5rem;
  padding: 0 1rem;
  font-weight: 600;
}

.docs-content {
  margin-left: var(--sidebar-width);
  padding: 3rem 4rem;
  max-width: 900px;
  width: 100%;
  transition: margin-left 0.3s ease;
}

.docs-content.expanded {
  margin-left: 0;
  max-width: 1200px;
  margin: 0 auto;
}

/* Home Container (No Sidebar) */
.home-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 4rem 2rem;
  width: 100%;
}

/* Components */
.hero {
  padding: 4rem 0 3rem;
  text-align: left;
}

.hero p {
  font-size: 1.25rem;
  max-width: 800px;
}

.hero .cta-group {
  display: flex;
  gap: 1rem;
  margin-top: 2rem;
  flex-wrap: wrap;
}

.btn-primary {
  display: inline-block;
  background: var(--accent-cyan);
  color: #000 !important;
  font-weight: 600;
  padding: 0.75rem 1.5rem;
  border-radius: 6px;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.btn-primary:hover {
  opacity: 0.9;
  transform: translateY(-1px);
}

.btn-secondary {
  display: inline-block;
  background: var(--bg-tertiary);
  color: var(--text-primary) !important;
  font-weight: 600;
  padding: 0.75rem 1.5rem;
  border-radius: 6px;
  border: 1px solid var(--border-color);
  transition: background 0.2s ease;
}

.btn-secondary:hover {
  background: var(--bg-secondary);
  border-color: var(--text-secondary);
}

/* Grid & Cards */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 1.5rem;
  margin: 2rem 0;
}

.card {
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  transition: border-color 0.2s ease, transform 0.2s ease;
  backdrop-filter: blur(10px);
}

.card h3 {
  margin-top: 0;
  margin-bottom: 1rem;
}

.card p {
  font-size: 1rem;
  flex-grow: 1;
}

.card:hover {
  border-color: var(--border-hover);
  transform: translateY(-2px);
}

/* Code Blocks & CLI Section */
.cli-setup {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  margin: 3rem 0;
  overflow: hidden;
}

.accordion-header {
  padding: 1.25rem 1.5rem;
  background: var(--bg-tertiary);
  border-bottom: 1px solid var(--border-color);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
  transition: background 0.2s ease;
}

.accordion-header:hover {
  background: rgba(255, 255, 255, 0.05);
}

.accordion-header.active {
  border-left: 3px solid var(--accent-cyan);
}

.accordion-content {
  padding: 1.5rem;
  display: none;
  background: var(--bg-primary);
}

.accordion-content.active {
  display: block;
}

.tabs-container {
  margin-top: 1.5rem;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  overflow: hidden;
}

.tab-header {
  display: flex;
  background: var(--bg-tertiary);
  border-bottom: 1px solid var(--border-color);
}

.tab-btn {
  background: none;
  border: none;
  padding: 0.75rem 1.5rem;
  color: var(--text-secondary);
  cursor: pointer;
  font-family: var(--font-mono);
  font-size: 0.9rem;
  font-weight: 600;
}

.tab-btn.active {
  color: var(--text-primary);
  border-bottom: 2px solid var(--accent-cyan);
}

.tab-btn:hover:not(.active) {
  color: var(--text-primary);
  background: rgba(255, 255, 255, 0.05);
}

.tab-pane {
  display: none;
  padding: 1.5rem;
  background: #0d1117;
  color: #a5d6ff;
  font-family: var(--font-mono);
  font-size: 0.95rem;
  line-height: 1.5;
  overflow-x: auto;
}

.tab-pane.active {
  display: block;
}

code {
  font-family: var(--font-mono);
  background: var(--bg-tertiary);
  padding: 0.2rem 0.4rem;
  border-radius: 4px;
  font-size: 0.9em;
}

pre {
  background: var(--bg-tertiary);
  padding: 1rem;
  border-radius: 6px;
  overflow-x: auto;
  border: 1px solid var(--border-color);
  margin-bottom: 1.5rem;
}

pre code {
  background: transparent;
  padding: 0;
  border-radius: 0;
}

/* Footer */
footer {
  border-top: 1px solid var(--border-color);
  padding: 4rem 2rem;
  background: var(--bg-primary);
  margin-top: 4rem;
}

.footer-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
}

.footer-col h4 {
  font-size: 1rem;
  margin-bottom: 1rem;
  color: var(--text-primary);
}

.footer-col ul {
  list-style: none;
  margin-left: 0;
}

.footer-col li {
  margin-bottom: 0.5rem;
}

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.9rem;
}

.footer-col a:hover {
  color: var(--accent-cyan);
}

/* Utility classes */
.mb-1 { margin-bottom: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.mb-3 { margin-bottom: 1.5rem; }
.mb-4 { margin-bottom: 2rem; }
.mt-2 { margin-top: 1rem; }
.mt-4 { margin-top: 2rem; }

/* Responsive */
@media (max-width: 768px) {
  .sidebar { transform: translateX(-100%); width: 260px; z-index: 50; }
  .sidebar.active { transform: translateX(0); }
  .docs-content { margin-left: 0; padding: 2rem 1.5rem; }
  .nav-links { display: none; }
  .hero h1 { font-size: 2rem; }
}

document.addEventListener('DOMContentLoaded', () => {

  // Accordion Logic
  const accordions = document.querySelectorAll('.accordion-header');
  accordions.forEach(acc => {
    acc.addEventListener('click', () => {
      // Close all others
      accordions.forEach(other => {
        if (other !== acc) {
          other.classList.remove('active');
          const otherContent = document.getElementById(other.getAttribute('aria-controls'));
          if(otherContent) otherContent.classList.remove('active');
        }
      });
      // Toggle current
      acc.classList.toggle('active');
      const content = document.getElementById(acc.getAttribute('aria-controls'));
      if(content) content.classList.toggle('active');
    });
  });

  // Tab Logic
  const tabBtns = document.querySelectorAll('.tab-btn');
  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const targetId = btn.getAttribute('data-target');
      if(!targetId) return;

      const group = btn.closest('.tabs-container');
      if(!group) return;

      // Deactivate all in group
      group.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
      group.querySelectorAll('.tab-pane').forEach(p => p.classList.remove('active'));

      // Activate selected
      btn.classList.add('active');
      const targetPane = document.getElementById(targetId);
      if(targetPane) targetPane.classList.add('active');
    });
  });

  // Sidebar Collapse Logic
  const sidebarToggle = document.getElementById('sidebar-toggle');
  const sidebar = document.querySelector('.sidebar');
  const docsContent = document.querySelector('.docs-content');

  if (sidebarToggle && sidebar && docsContent) {
    sidebarToggle.addEventListener('click', () => {
      sidebar.classList.toggle('collapsed');
      docsContent.classList.toggle('expanded');
    });
  }

  // Dark Mode Toggle
  const themeToggle = document.getElementById('theme-toggle');
  if (themeToggle) {
    themeToggle.addEventListener('click', () => {
      const currentTheme = document.documentElement.getAttribute('data-theme') || 'dark';
      const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', newTheme);
    });
  }

  // Mobile menu simulation (if needed)
  const mobileMenuToggle = document.getElementById('mobile-menu-toggle');
  if (mobileMenuToggle && sidebar) {
    mobileMenuToggle.addEventListener('click', () => {
      sidebar.classList.toggle('active');
    });
  }
});

